import { createHash, createHmac } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import type { StorageConfig } from '../../env.ts';

/** Where uploaded bytes live. Keys are opaque, generated by Ordo (never user input). */
export interface Storage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
  /** For the admin health page. */
  describe(): string;
}

export function createStorage(config: StorageConfig): Storage {
  return config.driver === 's3' ? new S3Storage(config) : new LocalStorage(config.dir);
}

class LocalStorage implements Storage {
  constructor(private root: string) {}

  private path(key: string) {
    const p = resolve(this.root, key);
    if (!p.startsWith(resolve(this.root))) throw new Error('Invalid storage key');
    return p;
  }

  async put(key: string, body: Buffer) {
    const p = this.path(key);
    await mkdir(dirname(p), { recursive: true });
    await writeFile(p, body);
  }

  async get(key: string) {
    try {
      return await readFile(this.path(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async delete(key: string) {
    await rm(this.path(key), { force: true });
  }

  describe() {
    return `local disk (${this.root})`;
  }
}

/**
 * S3-compatible object storage (AWS S3, MinIO, Garage, Cloudflare R2, Backblaze B2…), signed
 * with a minimal AWS Signature V4 implementation so the bundle needs no SDK.
 */
class S3Storage implements Storage {
  constructor(private c: Extract<StorageConfig, { driver: 's3' }>) {}

  private url(key: string) {
    const encoded = key.split('/').map(encodeURIComponent).join('/');
    const endpoint = new URL(this.c.endpoint);
    return this.c.forcePathStyle
      ? new URL(`${endpoint.origin}/${this.c.bucket}/${encoded}`)
      : new URL(`${endpoint.protocol}//${this.c.bucket}.${endpoint.host}/${encoded}`);
  }

  private async request(method: string, key: string, body?: Buffer, contentType?: string) {
    const url = this.url(key);
    const payloadHash = sha256hex(body ?? Buffer.alloc(0));
    const now = new Date();
    const amzDate = now.toISOString().replace(/[-:]|\.\d{3}/g, '');
    const day = amzDate.slice(0, 8);
    const headers: Record<string, string> = {
      host: url.host,
      'x-amz-content-sha256': payloadHash,
      'x-amz-date': amzDate,
    };
    if (contentType) headers['content-type'] = contentType;
    const signedHeaders = Object.keys(headers).sort();
    const canonical = [
      method,
      url.pathname,
      '',
      ...signedHeaders.map((h) => `${h}:${headers[h]}`),
      '',
      signedHeaders.join(';'),
      payloadHash,
    ].join('\n');
    const scope = `${day}/${this.c.region}/s3/aws4_request`;
    const toSign = ['AWS4-HMAC-SHA256', amzDate, scope, sha256hex(Buffer.from(canonical))].join(
      '\n',
    );
    let k: Buffer = hmac(`AWS4${this.c.secretAccessKey}`, day);
    for (const part of [this.c.region, 's3', 'aws4_request']) k = hmac(k, part);
    const signature = hmac(k, toSign).toString('hex');
    headers.authorization = `AWS4-HMAC-SHA256 Credential=${this.c.accessKeyId}/${scope}, SignedHeaders=${signedHeaders.join(';')}, Signature=${signature}`;
    delete headers.host;
    return fetch(url, { method, headers, body });
  }

  async put(key: string, body: Buffer, contentType: string) {
    const res = await this.request('PUT', key, body, contentType);
    if (!res.ok) throw new Error(`S3 PUT ${key} failed: ${res.status} ${await res.text()}`);
  }

  async get(key: string) {
    const res = await this.request('GET', key);
    if (res.status === 404) return null;
    if (!res.ok) throw new Error(`S3 GET ${key} failed: ${res.status}`);
    return Buffer.from(await res.arrayBuffer());
  }

  async delete(key: string) {
    const res = await this.request('DELETE', key);
    if (!res.ok && res.status !== 404) throw new Error(`S3 DELETE ${key} failed: ${res.status}`);
  }

  describe() {
    return `S3 bucket ${this.c.bucket} at ${this.c.endpoint}`;
  }
}

const sha256hex = (b: Buffer) => createHash('sha256').update(b).digest('hex');
const hmac = (key: string | Buffer, data: string) =>
  createHmac('sha256', key).update(data).digest();

export const storageKey = (...parts: string[]) => join(...parts).replace(/\\/g, '/');
